if(c){const cell=f=>`<div><h3>${escape(f.label)}</h3><strong>${Number.isFinite(f.value)?fmt(f.value):'Variable'}</strong>${Number.isFinite(f.value)?'<span>acre-ft</span>':''}<p class="date">${escape(f.period.start.slice(0,4)==='2026'?'Jan 1–Dec 31, 2026':'Jan 1–Dec 31, 2025')}<br>Source ${escape(/^\d{4}-\d{2}-\d{2}$/.test(f.releaseDate)?dateLabel(f.releaseDate):f.releaseDate)}</p>${sourceLink(f.sourceId)}</div>`;h+=`<section class="accounting ${timeMode!=='latest'?'annual-context':''}"><p class="date">Entitlement and actual use · own reporting years</p><div class="account-pair">${cell(c.current)}${cell(c.actual)}</div>${c.basic?`<p class="date">Basic apportionment ${fmt(c.basic)} acre-ft / year<br>2026 shortage + DCP ${fmt(c.shortage)} acre-ft · Jan 1–Dec 31</p>`:''}<p class="date">${escape(c.note)}</p>`;if(c.available){const delta=accountingDifference(c.available,c.actual);h+=`<details id="matched-accounting"><summary>Matched 2025 accounting</summary><p>Available after all adjustments: <strong>${fmt(c.available.value)} acre-ft</strong></p><p>Consumed: <strong>${fmt(c.actual.value)} acre-ft</strong></p>${delta!==null?`<p>Available minus consumed: <strong>${fmt(delta)} acre-ft</strong></p>`:''}<p class="date">Same state, mainstream consumption, CY 2025 · Reclamation Table 11 · May 15, 2026. Includes conservation and storage adjustments; not a rights-compliance verdict.</p></details>`}h+='</section>'}
