async function boot(){ready=false;$('loading').hidden=false;$('retry').hidden=true;try{$('stage').textContent='Reading geography and dated observations';const r=await fetch('data/overview-lite.json');if(!r.ok)throw new Error('Geography could not be read');data=await r.json();$('stage').textContent='Preparing terrain';storyRelief=new Image();storyRelief.src='data/relief-storybook.webp';await storyRelief.decode();relief=null;$('stage').textContent='Making places selectable';entities=new Map(data.entities.map(e=>[e.id,e]));paths=data.features.map(f=>({...f,...makePath(f.geometry),...(f.overviewGeometry?{overviewPath:makePath(f.overviewGeometry).path}:{}),...(f.kind==='river'?{riverLods:makeRiverLods(f.geometry)}:{}),...(f.beyondGeometry?{beyondPath:makeRiverLods(f.beyondGeometry).mid}:{})}));for(const name of ['land','states','countries'])data[name==='land'?'landPaths':name==='states'?'statePaths':'countryPaths']=data[name].map(f=>makePath(outlineGeometry(name,f.geometry,data.bounds)));buildIndex();resize();Object.assign(cam,homeCam());try{const saved=JSON.parse(sessionStorage.getItem('water-atlas-state'));if(saved?.v===1&&Number.isFinite(saved.camera.s)&&saved.camera.s>0){Object.assign(cam,saved.camera);saved.layers.snow=false;for(const k in layers)if(typeof saved.layers[k]==='boolean')layers[k]=saved.layers[k];if(saved.timeMode==='latest'||data.months.includes(saved.timeMode))timeMode=saved.timeMode;updateTimeUI();if(entities.has(saved.selected))select(saved.selected,saved.marker)}}catch{}$('stage').textContent='Drawing the opening scene';await new Promise(requestAnimationFrame);draw();await new Promise(requestAnimationFrame);ready=true;telemetry.readyMs=performance.now();$('loading').hidden=true;setScope(scopeMode,{fly:false});schedule();if(!selected)showHint();window.ATLAS={get ready(){return ready},get base(){return base},toggleLayer(k,on){layers[k]=on;schedule()},watershedLabels(){return watershedLabels.map(l=>l.w.name)},get scope(){return scopeMode},get hint(){return{on:hintOn}},showHintForQA(){forceHint()},get scopeTowns(){return scopeTownHits.map(h=>({name:h.t.name,x:(h.x0+8),y:(h.y0+10)}))},get camera(){return{...cam}},get timeMode(){return timeMode},get selection(){return selected},get traceIds(){return trace?[...trace.ids]:[]},get telemetry(){return telemetry},get visiblePointIds(){return [...visiblePoints]},screenGeo:p=>screen(project(p)),entities:[...entities.values()],layers,get fineReady(){return !!fine.ready},get labeledPointIds(){return [...labeledPoints]},get animationFrame(){return animationFrame?{...animationFrame}:null},get visiblePlaceLabels(){return [...visiblePlaces]},get baseScale(){return base},get whereReady(){return !!whereData&&!!cropCounties},get cropTilesReady(){return cropPending.size===0&&cropTiles.size>0},get whereCircles(){return whereVisible.map(c=>({kind:c.kind,id:c.item.id,x:c.x,y:c.y,r:c.r}))},get capPlantsVisible(){return capPlantsVisible},get terrainDetail(){return {zoom:terrainZ,tiles:terrainTiles.size,failed:terrainFailed,want:terrainWant,have:terrainHave}},get terrainOption(){return terrainOption},setCamera(lon,lat,zoom){cam.x=lon*.8;cam.y=-lat;cam.s=base*zoom;schedule()}};}catch(e){$('stage').textContent=e.message+' — the map is not ready.';$('retry').hidden=false;}}// ---- M17: show that the map is clickable ----
